const RETRYABLE = [404, 408, 429, 500, 502, 503, 504]

// Same check as the browser's (src/content/landing.ts): placeholder or keyboard-mash text never reaches the model.
const FILLER = new Set(['test', 'testing', 'tests', 'asdf', 'qwerty', 'azerty', 'lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing', 'elit', 'sed', 'eiusmod', 'tempor', 'incididunt', 'labore', 'magna', 'aliqua', 'blah', 'bla', 'xxx', 'xx', 'x', 'aaa', 'abc', 'foo', 'bar', 'baz', 'idk', 'dunno', 'something', 'stuff', 'whatever', 'todo', 'tbd', 'na', 'n/a', 'none', 'nothing', 'hello', 'hi', 'ok', 'okay', 'yes', 'no', 'answer', 'here', 'random', 'text', 'word', 'words'])
const KEYS = ['qwer', 'wert', 'erty', 'asdf', 'sdfg', 'dfgh', 'fghj', 'ghjk', 'hjkl', 'zxcv', 'xcvb', 'cvbn', 'vbnm', 'azer', 'qsdf', 'uiop', 'yuio', 'jkl;']
const gibberish = (w: string) => w.length >= 4 && (/[bcdfghjklmnpqrstvwxz]{5,}/.test(w) || KEYS.some((k) => w.includes(k)) || /^(.{2,4})\1+.?$/.test(w))
function isJunk(text: string) {
  const ws = (text.toLowerCase().match(/[\p{L}\p{N}'’-]+/gu) ?? []).filter(Boolean)
  if (!ws.length) return false
  if (ws.filter((w) => FILLER.has(w)).length / ws.length >= 0.5) return true
  if (ws.length >= 4 && new Set(ws).size / ws.length < 0.35) return true
  const letters = ws.join('')
  if (letters.length >= 8 && !/[aeiouy]/.test(letters)) return true
  if (ws.some((w) => w.length > 25)) return true
  const long = ws.filter((w) => w.length >= 4)
  return long.length > 0 && long.filter(gibberish).length / long.length >= 0.4
}
// answers arrive as "question\n- answer" lines; check every written answer of three words or more
const hasJunk = (answer: string) =>
  answer
    .split('\n')
    .map((l) => l.replace(/^\s*-\s*/, '').replace(/^[^:]{0,60}:\s*/, ''))
    .some((l) => l.trim().split(/\s+/).length >= 3 && isJunk(l))

// Try each model in turn until one answers, within the time budget.
async function callGemini(prompt: string, schema: object, maxTokens: number, first: string) {
  const start = Date.now()
  const order = [first, ...CHAIN.filter((m) => m !== first)]
  let last: { status?: number; message?: string } = {}
  for (const model of order) {
    for (const light of [true, false]) {
      const left = BUDGET_MS - (Date.now() - start)
      if (left < 2500) throw Object.assign(new Error('budget'), { status: last.status ?? 504, tried: model })
      try {
        // the first model gets a shorter leash so a slow or overloaded one hands over quickly
        const out = await callGeminiOnce(prompt, schema, maxTokens, light, model, Math.min(left, model === order[0] ? 9000 : 12000))
        return { out, model }
      } catch (e) {
        last = e as { status?: number; message?: string }
        if (last.status === 400 && light) continue // this model rejects thinkingLevel: retry without it
        break
      }
    }
    if (!RETRYABLE.includes(last.status ?? 0) && last.status !== 400) throw last
  }
  throw Object.assign(new Error('all models failed'), { status: last.status ?? 502 })
}

async function callGeminiOnce(prompt: string, schema: object, maxTokens: number, light: boolean, model: string, timeout: number) {
  const key = process.env.GEMINI_API_KEY
  if (!key) throw Object.assign(new Error('no key'), { status: 503 })
  const ctl = new AbortController()
  const t = setTimeout(() => ctl.abort(), timeout)
  try {
    const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-goog-api-key': key },
      signal: ctl.signal,
      body: JSON.stringify({
        systemInstruction: { parts: [{ text: RULES }] },
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0.4,
          maxOutputTokens: maxTokens,
          responseMimeType: 'application/json',
          responseSchema: schema,
          ...(light ? { thinkingConfig: { thinkingLevel: 'low' } } : {}),
        },
      }),
    })
    if (!r.ok) throw Object.assign(new Error(`gemini ${r.status}`), { status: r.status })
    const data = (await r.json()) as { candidates?: { content?: { parts?: { text?: string; thought?: boolean }[] } }[] }
    const text = data.candidates?.[0]?.content?.parts?.filter((p) => !p.thought).map((p) => p.text ?? '').join('') ?? ''
    const json = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)
    try {
      return JSON.parse(json) as Record<string, unknown>
    } catch {
      throw Object.assign(new Error('bad json'), { status: 502 })
    }
  } catch (e) {
    if ((e as { name?: string }).name === 'AbortError') throw Object.assign(new Error('timeout'), { status: 504 })
    throw e
  } finally {
    clearTimeout(t)
  }
}

export default async function handler(req: Req, res: Res) {
  res.setHeader('cache-control', 'no-store')
  if (req.method !== 'POST') return res.status(405).json({ error: 'POST only' })
  const ip = String(req.headers['x-forwarded-for'] ?? req.socket?.remoteAddress ?? 'anon').split(',')[0].trim()
  const sid = String(req.headers['x-voyage'] ?? '').slice(0, 64)
  if (limited(ip, sid)) return res.status(429).json({ error: 'Too many requests from this network. Athena needs a breather.' })

  const b = (typeof req.body === 'string' ? JSON.parse(req.body || '{}') : req.body ?? {}) as Record<string, unknown>
  const kind = b.kind as TaskKind
  if (!KINDS.includes(kind)) return res.status(400).json({ error: 'unknown kind' })
  const directionId = typeof b.directionId === 'number' && b.directionId >= 1 && b.directionId <= 14 ? b.directionId : undefined
  const context = String(b.context ?? '').slice(0, 2000)
  const journey = String(b.journey ?? '').slice(0, 2000)
  const answer = String(b.answer ?? '').slice(0, MAX_CHARS)
  const previous = Array.isArray(b.previous) ? b.previous.slice(0, 5).map(String) : []

  if (b.mode !== 'hint' && hasJunk(answer)) {
    const rubric = RUBRICS[kind]
    return res.status(200).json({
      scores: rubric.map((c) => ({ criterion: c.key, score: 0, note: 'Placeholder text is not an answer.' })),
      feedback: 'There is nothing to review yet: part of this answer is placeholder text. Write what you really think, even roughly, and submit again.',
      question: 'What would you tell a real customer here, in your own words?',
      model: 'rules',
    })
  }
  try {
    if (b.mode === 'hint') {
      // the fast model answers nudges in a couple of seconds; the main model takes over if it fails
      const { out, model } = await callGemini(hintPrompt(kind, directionId, context, journey, answer, previous), HINT_SCHEMA, 2048, FAST)
      return res.status(200).json({ question: String(out.question ?? ''), model })
    }
    const { out, model } = await callGemini(gradePrompt(kind, directionId, context, journey, answer), GRADE_SCHEMA, 2048, kind === 'landing' ? FAST : MODEL)
    return res.status(200).json({ ...out, model })
  } catch (e) {
    const status = (e as { status?: number }).status ?? 502
    console.error('coach failed', status, (e as Error).message)
    return res.status(status === 429 ? 429 : 503).json({ error: status === 429 ? 'quota' : 'unavailable', upstream: status })
  }
}
